import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let fs = [1.5, 2.5]
    let r = fs.iterator().reduce(|p, q| p + q)
    match r {
        Some(v) => { io.println("sum ${v}") }
        None => { io.println("none") }
    }
    return Ok(())
}
